/** A lease is acquired synchronously and its operation settles asynchronously. */
export function execute({ pool, child }) {
  const lease = pool.acquire();
  const release = () => pool.release(lease);
  const response = (async () => {
    try { return await child; } finally { release(); }
  })();
  return { response, release };
}

/** Original deterministic controls; no wall clock, network or model calls. */
export function deferred() {
  let resolve, reject;
  const promise = new Promise((yes, no) => { resolve = yes; reject = no; });
  return { promise, resolve, reject };
}
export class SlotPool {
  #leases = new Set();
  constructor(capacity = 1) { this.capacity = capacity; this.started = 0; this.released = 0; }
  acquire() {
    if (this.#leases.size >= this.capacity) throw new Error('capacity');
    const lease = Symbol('lease'); this.#leases.add(lease); this.started++; return lease;
  }
  release(lease) { if (this.#leases.delete(lease)) { this.released++; return true; } return false; }
  get active() { return this.#leases.size; }
}

/** Cancellation can occur while preparation yields to its caller. */
export async function launch({ signal, gate, pool }) {
  if (signal.aborted) return { status: 'cancelled', complete() {} };
  await gate;
  // Cancellation is subscribed only after preparation.
  const lease = pool.acquire();
  const operation = { status: 'pending', complete: () => finish('ok') };
  function finish(status) {
    if (operation.status !== 'pending') return;
    operation.status = status; pool.release(lease);
    signal.removeEventListener('abort', cancel);
  }
  function cancel() { finish('cancelled'); }
  signal.addEventListener('abort', cancel, { once: true });
  return operation;
}

